const $=id=>document.getElementById(id),esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');let user=null;
const api=(path,opt={})=>window.EHSApi.request(path,opt);
function statusLabel(s){const m={not_started:['작성전','gray'],in_progress:['작성중','orange'],submitted:['제출완료','green'],evaluating:['평가중','orange'],completed:['평가완료','blue'],published:['결과공개','green']};const v=m[s]||[s||'-','gray'];return `<span class="status ${v[1]}">${esc(v[0])}</span>`}
function effectiveEvaluationStatus(row){return Number(row?.has_submission_record||0)===0&&row?.status==='submitted'?'in_progress':row?.status}
function route(){const p=location.pathname.replace(/\/+$/,'')||'/ipass';if(p==='/ipass/templates')return'templates';if(p==='/ipass/cycles')return'cycles';if(p==='/ipass/evaluations')return'evaluations';return'overview'}
function navItems(){return user?.role==='admin'?[['overview','/ipass','종합현황'],['evaluations','/ipass/evaluations','평가 현황'],['templates','/ipass/templates','평가표 관리'],['cycles','/ipass/cycles','평가회차 운영']]:[['overview','/ipass','요약'],['evaluations','/ipass/evaluations','평가 제출·이력']]}
function renderNav(){const active=route();$('sideNav').innerHTML=navItems().map(([key,path,label])=>`<button class="nav-btn ${active===key?'active':''}" type="button" data-route="${path}" ${active===key?'aria-current="page"':''}><span>${label}</span></button>`).join('');$('sideNav').querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route))}
function go(path){if(['/ipass/templates','/ipass/cycles'].includes(path)){location.href=path;return}if(location.pathname!==path)history.pushState({},'',path);renderNav();renderRoute()}window.addEventListener('popstate',()=>{renderNav();renderRoute()});
function panel(title,meta,body){return `<section class="panel"><div class="panel-head"><strong>${esc(title)}</strong><span>${esc(meta||'')}</span></div>${body}</section>`}
async function renderAdminOverview(){const box=$('content');box.innerHTML='<div class="panel"><div class="loading">종합현황을 불러오는 중...</div></div>';try{const d=await api('/api/admin/dashboard-bundle');const a=d.dashboard||{},cycle=d.cycles?.[0],target=Number(a.target_company_count||0),submitted=Number(a.submitted_count||0);box.innerHTML=`<div class="kpis"><div class="kpi"><span>평가대상</span><b>${target}</b></div><div class="kpi"><span>제출완료</span><b>${submitted}</b></div><div class="kpi"><span>평가중</span><b>${Number(a.evaluating_count||0)}</b></div><div class="kpi"><span>평가완료</span><b>${Number(a.completed_count||0)}</b></div><div class="kpi attention"><span>미제출</span><b>${Math.max(0,target-submitted)}</b></div></div>${panel('현재 평가회차',cycle?`${cycle.cycle_name} · ${cycle.start_at||'-'} ~ ${cycle.end_at||'-'}`:'운영 중인 평가회차가 없습니다.',`<div class="panel-body"><div class="quick-grid"><button class="quick" data-go="/ipass/evaluations"><strong>평가 현황</strong><span>협력사별 제출 및 평가 진행상태를 확인합니다.</span><em>현황 보기 ›</em></button><button class="quick" data-go="/ipass/templates"><strong>평가표 관리</strong><span>상·하반기 평가항목, 배점, 제출가이드와 N/A 기준을 관리합니다.</span><em>평가표 열기 ›</em></button><button class="quick" data-go="/ipass/cycles"><strong>평가회차 운영</strong><span>평가기간과 평가대상 협력사를 확정하고 회차를 시작·종료합니다.</span><em>회차 운영 ›</em></button></div></div>`)}`;box.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))}catch(e){box.innerHTML=`<div class="panel"><div class="error">${esc(e.message)}</div></div>`}}
async function renderAdminEvaluations(){const box=$('content');box.innerHTML='<div class="panel"><div class="loading">평가현황을 불러오는 중...</div></div>';try{const d=await api('/api/admin/dashboard-bundle'),list=(d.targets||[]).filter(x=>Number(x.is_selected)===1),cycle=d.cycles?.[0];box.innerHTML=panel('협력사 평가 현황',cycle?cycle.cycle_name:'현재 평가회차',list.length?`<div class="table-wrap"><table><thead><tr><th>협력사</th><th>업종</th><th>상시근로자</th><th>제출일</th><th>상태</th></tr></thead><tbody>${list.map(x=>{const effective=effectiveEvaluationStatus(x),ready=Number(x.has_submission_record||0)>0&&['submitted','evaluating','completed','published'].includes(effective);return `<tr class="${ready?'eval-row':''}" ${ready?`data-score-target="${esc(x.id)}"`:''}><td><b>${esc(x.company_name)}</b></td><td>${esc(x.industry_name||'-')}</td><td>${x.worker_count??'-'}</td><td>${esc(Number(x.has_submission_record||0)>0&&x.submitted_at?String(x.submitted_at).slice(0,10):'-')}</td><td>${statusLabel(effective)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">현재 평가대상이 없습니다.</div>');box.querySelectorAll('[data-score-target]').forEach(r=>r.onclick=()=>location.href='/evaluation-scoring.html?target='+encodeURIComponent(r.dataset.scoreTarget))}catch(e){box.innerHTML=`<div class="panel"><div class="error">${esc(e.message)}</div></div>`}}
let partnerDataPromise=null;
function partnerData(){if(!partnerDataPromise){const year=new Date().getFullYear();partnerDataPromise=Promise.all([api(`/api/annual-ipass?year=${year}`).catch(()=>({annual:{}})),api('/api/my/evaluations')]).then(([annual,evals])=>({year,annual:annual.annual||{},list:evals.evaluations||[]}))}return partnerDataPromise}
function partnerTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>평가회차</th><th>기간</th><th>상태</th></tr></thead><tbody>${list.map(x=>`<tr class="eval-row" tabindex="0" data-target="${esc(x.id)}"><td><b>${esc(x.cycle_name)}</b></td><td>${esc((x.start_at||'-')+' ~ '+(x.end_at||'-'))}</td><td>${statusLabel(effectiveEvaluationStatus(x))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">현재 배정된 평가가 없습니다.</div>'}
function bindPartnerRows(box){box.querySelectorAll('[data-target]').forEach(r=>{const open=()=>location.href='/evaluation-submit.html?target='+encodeURIComponent(r.dataset.target);r.onclick=open;r.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}})}
function submissionReturnNotice(){const params=new URLSearchParams(location.search);if(params.get('submitted')!=='1')return'';params.delete('submitted');params.delete('duration_ms');history.replaceState({},'',location.pathname+(params.size?'?'+params.toString():'')+location.hash);return '<div class="route-notice" role="status">평가자료가 제출되었습니다. 최신 상태를 반영했습니다.</div>'}
function scoreText(value){if(value==null||value==='')return'—';const n=Number(value);return Number.isFinite(n)?n.toFixed(n%1?1:0):'—'}
function scoreComponent(label,value,note){return `<div class="partner-score-component"><span>${esc(label)}</span><b>${esc(value)}</b><small title="${esc(note)}">${esc(note)}</small></div>`}
function partnerTaskCopy(status){if(status==='not_started')return'평가자료 작성을 시작해 주세요.';if(status==='in_progress')return'작성 중인 내용을 확인하고 기간 내 제출해 주세요.';if(status==='submitted')return'제출이 완료됐습니다. 평가기간에는 내용을 다시 확인할 수 있습니다.';if(status==='evaluating')return'관리자가 제출자료를 심사하고 있습니다.';return'평가 진행상태를 확인할 수 있습니다.'}
async function renderPartnerOverview(){const box=$('content');box.innerHTML='<div class="panel"><div class="loading">i-PaSS 정보를 불러오는 중...</div></div>';try{const {year,annual:a,list}=await partnerData(),total=a.final_total??a.current_reflected_score,max=a.final_total!=null?(a.score_cap||100):(a.current_reflected_max||60),score=scoreText(total),grade=a.final_grade||'산정 중',pending=list.filter(x=>!['completed','published'].includes(effectiveEvaluationStatus(x))),task=pending.find(x=>['not_started','in_progress'].includes(effectiveEvaluationStatus(x)))||pending[0],firstNote=a.first_half_exempt?'평가 면제':`${Number(a.first_half_weight??40)}점 반영`,deduction=Number(a.unreasonable_deduction||0),components=[scoreComponent(a.first_half_exempt?'상반기 면제':'상반기',a.first_half_exempt?'면제':scoreText(a.first_half_score),firstNote),scoreComponent('하반기',scoreText(a.second_half_score),`${Number(a.second_half_weight??40)}점 반영`),scoreComponent('협의체',scoreText(a.committee_score),`${Number(a.committee_weight??10)}점 반영`),scoreComponent('산업재해',scoreText(a.industrial_accident_score),deduction>0?`감점 ${scoreText(deduction)}점 포함`:`${Number(a.industrial_accident_weight??10)}점 반영`)].join('');let taskBody;if(task){const status=effectiveEvaluationStatus(task),action=['not_started','in_progress'].includes(status)?'자료 작성하기':'제출내용 확인';taskBody=`<div class="partner-task"><div>${statusLabel(status)}</div><div class="partner-task-name">${esc(task.cycle_name)}</div><div class="partner-task-period">${esc((task.start_at||'-')+' ~ '+(task.end_at||'-'))}</div><p class="partner-task-copy">${esc(partnerTaskCopy(status))}</p><div class="partner-task-actions"><button class="btn primary" type="button" data-target="${esc(task.id)}">${action}</button><button class="partner-history-link" type="button" data-go="/ipass/evaluations">전체 이력</button></div></div>`}else taskBody='<div class="partner-task-empty"><strong>현재 처리할 평가가 없습니다.</strong><p>새 평가가 배정되면 이곳에 바로 표시됩니다.</p><div class="partner-task-actions"><button class="partner-history-link" type="button" data-go="/ipass/evaluations">지난 평가 보기</button></div></div>';box.innerHTML=`<div class="partner-overview"><section class="partner-overview-card"><div class="partner-overview-head"><strong>${year}년 i-PaSS</strong><span>현재 반영 기준</span></div><div class="partner-score-summary"><div class="partner-score-copy"><div class="score-label">현재 반영점수</div><div class="score-line"><span class="score-value">${score}</span><span class="score-unit">/ ${scoreText(max)}점</span></div><span class="score-grade">${esc(grade)}</span></div><div class="partner-score-components">${components}</div></div></section><section class="partner-overview-card partner-task-card"><div class="partner-overview-head"><strong>지금 해야 할 평가</strong><span>${pending.length?`${pending.length}건 진행 중`:'대기 업무 없음'}</span></div>${taskBody}</section></div>`;bindPartnerRows(box);box.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))}catch(e){box.innerHTML=`<div class="panel"><div class="error">${esc(e.message)}</div></div>`}}
async function renderPartnerEvaluations(){const box=$('content');box.innerHTML='<div class="panel"><div class="loading">평가 이력을 불러오는 중...</div></div>';try{const {list}=await partnerData(),open=list.filter(x=>['not_started','in_progress'].includes(effectiveEvaluationStatus(x))).length,review=list.filter(x=>['submitted','evaluating'].includes(effectiveEvaluationStatus(x))).length,done=list.filter(x=>['completed','published'].includes(effectiveEvaluationStatus(x))).length;box.innerHTML=`${submissionReturnNotice()}<div class="kpis partner-kpis"><div class="kpi"><span>전체 평가</span><b>${list.length}</b></div><div class="kpi"><span>작성 필요</span><b>${open}</b></div><div class="kpi"><span>심사 중</span><b>${review}</b></div><div class="kpi"><span>완료</span><b>${done}</b></div></div>${panel('내 평가 전체 이력','평가행을 선택하면 제출 화면으로 이동합니다.',partnerTable(list))}`;bindPartnerRows(box)}catch(e){box.innerHTML=`<div class="panel"><div class="error">${esc(e.message)}</div></div>`}}
function renderAdminPage(type){location.href=type==='templates'?'/ipass/templates':'/ipass/cycles'}
function renderRoute(){const r=route();if(user?.role!=='admin')return r==='evaluations'?renderPartnerEvaluations():renderPartnerOverview();if(r==='templates')return renderAdminPage('templates');if(r==='cycles')return renderAdminPage('cycles');if(r==='evaluations')return renderAdminEvaluations();return renderAdminOverview()}
function goHome(){location.href='/home'}$('homeBtn').onclick=goHome;$('brandBtn').onclick=goHome;
(async function boot(){try{user=await window.EHSAuth.requireUser();window.__EHS_PAGE_USER=user;document.dispatchEvent(new CustomEvent('ehs:user-ready',{detail:user}));$('userLabel').textContent=[user.company_name,user.name].filter(Boolean).join(' · ');$('workspaceTitle').textContent=user.role==='admin'?'i-PaSS 관리':'i-PaSS';$('heroMeta').textContent=user.role==='admin'?'평가 현황, 평가표, 평가회차를 한 화면에서 관리합니다.':'점수 현황과 지금 처리할 평가를 확인합니다.';if(user.role!=='admin'&&!['/ipass','/ipass/','/ipass/evaluations'].includes(location.pathname))history.replaceState({},'', '/ipass');renderNav();renderRoute()}catch(e){if(e?.status===401)return;$('content').innerHTML=`<div class="panel"><div class="error">${esc(window.EHSApi?.describe?window.EHSApi.describe(e):e.message)}</div></div>`}})();
